'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const U={catalog:null,pages:[],index:null,dictionary:{},refs:new Map(),page:null,photo:null,view:'paper',mode:'word',panel:'explanation',question:null,zoom:1,refPage:1,refCandidates:[],lookup:null,records:{},busy:false,storageDamaged:false,abort:null,queue:[],worker:null,urls:[],loadToken:0};
const RECORD_KEY='english-universal.records.v1';let toastTimer,dbPromise;
function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4200)}
function dialog(title,html){$('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal()}
async function json(url){const r=await fetch(url);if(!r.ok)throw Error('资料加载失败，请检查网络后重试。');return r.json()}
function photoDB(){return dbPromise??=new Promise((resolve,reject)=>{const r=indexedDB.open('english-universal',1);r.onupgradeneeded=()=>r.result.createObjectStore('photos',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(Error('当前浏览器不能保存照片'))})}
async function dbAction(mode,fn){const db=await photoDB();return new Promise((resolve,reject)=>{const tx=db.transaction('photos',mode);const req=fn(tx.objectStore('photos'));let value;req.onsuccess=()=>value=req.result;tx.oncomplete=()=>resolve(value);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
function validateRecords(raw){if(!raw||raw.schema!==1||!raw.records||Array.isArray(raw.records)||typeof raw.records!=='object')throw Error('不是通用版学习记录');const out={};for(const [key,v]of Object.entries(raw.records)){if(!/^(201\d|202[0-6])-(?:[1-9]|[1-3]\d|4[0-8])$/.test(key)||!v||typeof v!=='object'||![null,'A','B','C','D','E','F','G'].includes(v.answer)||typeof v.note!=='string'||v.note.length>3000)throw Error('记录含无效题号、答案或笔记');out[key]={answer:v.answer,note:v.note,updatedAt:typeof v.updatedAt==='string'?v.updatedAt:''}}return out}
function saveRecords(){try{if(U.storageDamaged){const original=localStorage.getItem(RECORD_KEY);if(original)localStorage.setItem(RECORD_KEY+'.recovery',original);U.storageDamaged=false}localStorage.setItem(RECORD_KEY,JSON.stringify({schema:1,records:U.records}))}catch{toast('记录保存失败，请从“学习记录”导出备份')}}
function activeQuestions(){if(!U.page)return [];const p=U.page.page<=10&&U.page.page%2===1?U.pages.find(p=>p.year===U.page.year&&p.page===U.page.page+1):U.page;return p?.questions||[]}
function recordKey(){return U.page.year+'-'+U.question}
function sourceText(){const q=activeQuestions().find(q=>q.number===U.question);return q&&q.text.length>35?q.text:U.page.text}
function meta(year){return U.catalog.years.find(y=>y.year===year)}
async function references(year){if(U.refs.has(year))return U.refs.get(year);const m=meta(year);if(!m.reference)return [];const pages=await json(m.reference);U.refs.set(year,pages);return pages}
async function openPage(page,photo=null,message='从资料库打开'){if(!page){toast('资料库还未加载完成，请稍后重试');return}U.loadToken++;U.page=page;U.photo=photo;U.view=photo?'photo':'paper';U.question=photo?.questionNumber||activeQuestions()[0]?.number||null;U.panel='explanation';U.lookup=null;U.zoom=1;$('#home').hidden=true;$('#workbench').hidden=false;$('#workTitle').textContent=page.year+' 英语二 · '+page.section;$('#matchStatus').textContent=message+' · 真题第 '+page.page+' 页';$('#pageSelect').innerHTML=U.pages.filter(p=>p.year===page.year).map(p=>'<option value="'+p.id+'" '+(p.id===page.id?'selected':'')+'>第 '+p.page+' 页 · '+p.section+'</option>').join('');renderSource();renderQuestions();await showExplanation();window.scrollTo({top:0,behavior:'smooth'})}
function renderSource(){document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',U.view===b.dataset.view);b.disabled=b.dataset.view==='photo'&&!U.photo});document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',U.mode===b.dataset.mode));const box=$('#sourceContent'),p=U.page;$('#sourceHint').textContent=U.view==='photo'?'你的作答照片 · 点击印刷文字点读；手写答案请在右侧核对。':U.view==='text'?'电子档文字可能有识别误差，可切回“清晰原题”核对。':'原题电子页 · 点击单词查词，切换“句子”定位译文与讲解。';if(U.view==='text'){box.innerHTML='<div class="text-sheet" style="font-size:'+(19*U.zoom)+'px">'+p.words.map((w,i)=>'<button data-word-index="'+i+'">'+esc(w.text)+'</button>'+((p.words[i+1]?.y||0)-w.y>1?'\n':' ')).join('')+'</div>'}else{const photo=U.view==='photo',words=photo?U.photo.words:p.words;box.innerHTML='<div class="source-image" style="width:'+U.zoom*100+'%"><img src="'+esc(photo?U.photo.url:p.image)+'" alt="'+p.year+' 英语二第 '+p.page+' 页"><svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-label="文字点读层">'+words.map((w,i)=>'<rect class="hit" data-hit="'+i+'" x="'+w.x+'" y="'+w.y+'" width="'+w.w+'" height="'+w.h+'" tabindex="0" role="button" aria-label="'+esc(w.text)+'"/>').join('')+'</svg></div>'}box.scrollTop=0}
function renderQuestions(){const qs=activeQuestions();$('#questionBar').innerHTML=qs.map(q=>'<button data-question="'+q.number+'" class="'+(q.number===U.question?'active':'')+'">'+q.number+'</button>').join('');const box=$('#answerEditor');if(!U.question){box.innerHTML='';return}const r=U.records[recordKey()]||{answer:null,note:''},options=U.question<=40?'ABCD':U.question<=45?'ABCDEFG':'';box.innerHTML='<div class="answer-editor"><div class="answer-options"><span>第 '+U.question+' 题 · 我的原始答案</span>'+options.split('').map(a=>'<button data-answer="'+a+'" class="'+(r.answer===a?'active':'')+'">'+a+'</button>').join('')+(options?'<button id="clearChoice">清空</button>':'')+'</div><textarea id="answerNote" maxlength="3000" placeholder="记录作答思路、错因，或填写翻译与作文的复盘笔记" aria-label="第 '+U.question+' 题笔记">'+esc(r.note)+'</textarea><small>以你确认的选项为准；系统不会把涂改笔迹直接作为判分依据。</small></div>';$('#answerNote').oninput=e=>{const key=recordKey();U.records[key]={...(U.records[key]||{answer:null}),note:e.target.value,updatedAt:new Date().toISOString()};saveRecords()};$('#clearChoice')?.addEventListener('click',()=>setAnswer(null))}
function setAnswer(answer){const key=recordKey();U.records[key]={...(U.records[key]||{note:''}),answer,updatedAt:new Date().toISOString()};saveRecords();renderQuestions()}
function setPanel(panel){U.panel=panel;document.querySelectorAll('[data-panel]').forEach(b=>b.classList.toggle('active',panel===b.dataset.panel))}
async function showExplanation(query=sourceText(),sentence=false){const token=++U.loadToken;setPanel(sentence?'lookup':'explanation');$('#detailContent').innerHTML='<div class="empty">正在定位解析…</div>';try{const refs=await references(U.page.year);if(token!==U.loadToken)return;if(!refs.length){$('#detailContent').innerHTML='<div class="empty"><h3>原题已对应，解析待补充</h3><p>'+U.page.year+' 年的解析尚未加入资料库。你的照片、选项和笔记仍可保存。</p><p>提供这一年的解析 PDF 后，即可补充关联。</p></div>';return}const ranked=ExamMatch.references(query,refs,4,sentence?null:U.question);U.refCandidates=ranked.map(r=>r.page.page);U.refPage=U.refCandidates[0]||1;renderReference(sentence?query:null,ranked.length>0)}catch(e){if(token===U.loadToken)$('#detailContent').innerHTML='<div class="error-box">'+esc(e.message)+'<button id="retryRefs">重新加载</button></div>';$('#retryRefs')?.addEventListener('click',()=>showExplanation(query,sentence))}}
function renderReference(sentence=null,matched=true){const refs=U.refs.get(U.page.year)||[],ref=refs.find(p=>p.page===U.refPage);if(!ref)return;const box=$('#detailContent');box.innerHTML=(sentence?'<div class="sentence-box">'+esc(sentence)+'</div><p class="muted">下面定位原书中的对应内容，可查看句子译文、语法分析和上下文。这里展示原书页面，不将识别结果冒充逐句译文。</p>':'')+'<div class="ref-label">'+(matched?'已按'+(U.question&&!sentence?'第 '+U.question+' 题':'当前原文')+'定位原书相关页':'未找到足够明确的对应页，可用页码浏览解析')+'<br>'+esc(meta(U.page.year).sourceReference)+' · 第 '+U.refPage+' 页</div><div class="ref-pages">'+U.refCandidates.map((n,i)=>'<button data-ref="'+n+'" class="'+(n===U.refPage?'active':'')+'">'+(i===0?'最相关':'相关')+' · '+n+' 页</button>').join('')+'</div><div class="ref-nav"><button id="refPrev" '+(U.refPage<=1?'disabled':'')+'>← 上页</button><select id="refSelect" aria-label="解析页码">'+refs.map(r=>'<option value="'+r.page+'" '+(r.page===U.refPage?'selected':'')+'>第 '+r.page+' 页</option>').join('')+'</select><button id="refNext" '+(U.refPage>=refs.length?'disabled':'')+'>下页 →</button><button id="refEnlarge">放大查看</button></div><img class="reference-image" id="referenceImage" src="'+esc(ref.image)+'" alt="'+U.page.year+' 年原书解析第 '+ref.page+' 页"><p class="muted">解析可能跨页；点击下页继续。原书页码以当前 PDF 页序为准。</p>'+(U.page.year===2010?'<a class="ref-link" href="2010/" target="_blank" rel="noopener">打开 2010 精读版：逐题讲解、整句译文与独立重做 ↗</a>':'');function move(n){U.refPage=Math.max(1,Math.min(refs.length,n));renderReference(sentence,matched)}$('#refPrev').onclick=()=>move(U.refPage-1);$('#refNext').onclick=()=>move(U.refPage+1);$('#refSelect').onchange=e=>move(Number(e.target.value));document.querySelectorAll('[data-ref]').forEach(b=>b.onclick=()=>move(Number(b.dataset.ref)));const enlarge=()=>dialog(U.page.year+' 年解析 · 第 '+U.refPage+' 页','<img class="full-ref" src="'+esc(ref.image)+'" alt="原书解析放大图">');$('#refEnlarge').onclick=enlarge;$('#referenceImage').onclick=enlarge;box.scrollTop=0}
function sentenceAt(index){const ws=U.page.words;if(index===null||index===undefined||!ws[index])return null;let lo=index,hi=index;while(lo>0&&index-lo<45&&!/[.!?]["”']?$/.test(ws[lo-1].text))lo--;while(hi<ws.length-1&&hi-index<55&&!/[.!?]["”']?$/.test(ws[hi].text))hi++;return ws.slice(lo,hi+1).map(w=>w.text).join(' ')}
function dictionaryWord(text){const word=text.toLowerCase().replace(/^[^a-z]+|[^a-z']+$/g,'').replace(/'s$/,'');const candidates=[word,word.endsWith('s')?word.slice(0,-1):word,word.endsWith('es')?word.slice(0,-2):word,word.endsWith('ies')?word.slice(0,-3)+'y':word,word.endsWith('ing')?word.slice(0,-3):word,word.endsWith('ing')?word.slice(0,-3)+'e':word,word.endsWith('ed')?word.slice(0,-2):word,word.endsWith('ed')?word.slice(0,-1):word];for(const lemma of candidates)if(U.dictionary[lemma])return {word,lemma,...U.dictionary[lemma]};return {word,zh:null}}
function lookup(text,index){const sentence=sentenceAt(index);U.lookup={text,index,sentence};setPanel('lookup');if(U.mode==='sentence'){if(!sentence){$('#detailContent').innerHTML='<div class="empty">这一处文字没有可靠对应到原题，请切换“清晰原题”点击同一句。</div>';return}showExplanation(sentence,true);return}U.loadToken++;const entry=dictionaryWord(text);$('#detailContent').innerHTML='<div class="eyebrow">WORD · 单词释义</div><h2 class="lookup-word">'+esc(entry.word||text)+'</h2><p class="muted">'+esc(entry.phonetic?'/'+entry.phonetic+'/':'')+(entry.lemma&&entry.lemma!==entry.word?' · 原形 '+esc(entry.lemma):'')+'</p><div class="definition">'+esc(entry.zh||'未收录此拼写，请对照清晰原题核对，或查看所在句子的原书解析。')+'</div>'+(sentence?'<h3 style="font-size:12px;margin-top:25px">所在句子</h3><div class="sentence-box">'+esc(sentence)+'</div><button id="wholeSentence" style="width:100%">查看整句对应译文与解析</button>':'')+'<p class="muted">基础词典：ECDICT。请结合上下文选择词义。</p>';$('#wholeSentence')?.addEventListener('click',()=>{U.mode='sentence';document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===U.mode));showExplanation(sentence,true)});if(innerWidth<=760)$('#detailContent').scrollIntoView({behavior:'smooth',block:'start'})}
function cancelled(){return new DOMException('已取消识别','AbortError')}
function raceAbort(promise,signal){if(signal.aborted)return Promise.reject(cancelled());return new Promise((resolve,reject)=>{const abort=()=>reject(cancelled());signal.addEventListener('abort',abort,{once:true});promise.then(v=>{signal.removeEventListener('abort',abort);resolve(v)},e=>{signal.removeEventListener('abort',abort);reject(e)})})}
async function worker(signal){if(!globalThis.Tesseract)await raceAbort(new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='2010/vendor/tesseract.min.js';s.onload=resolve;s.onerror=()=>reject(Error('识别组件未加载成功，请重试'));document.head.appendChild(s)}),signal);if(!U.worker){const promise=Tesseract.createWorker('eng',1,{workerPath:new URL('2010/vendor/worker.min.js',location.href).href,corePath:new URL('2010/vendor/',location.href).href,langPath:new URL('2010/vendor',location.href).href,workerBlobURL:false,logger:m=>{if(U.busy&&$('#ocrStatus'))$('#ocrStatus').textContent=m.status==='recognizing text'?'识别印刷文字 '+Math.round(m.progress*100)+'%':'正在准备识别组件…'}});promise.then(w=>{if(signal.aborted)w.terminate();else U.worker=w}).catch(()=>{});await raceAbort(promise,signal)}return U.worker}
function canvasFor(bitmap,angle){const s=Math.min(1,2200/Math.max(bitmap.width,bitmap.height)),w=Math.round(bitmap.width*s),h=Math.round(bitmap.height*s),c=document.createElement('canvas');c.width=angle%180?h:w;c.height=angle%180?w:h;const g=c.getContext('2d');g.fillStyle='white';g.fillRect(0,0,c.width,c.height);g.translate(c.width/2,c.height/2);g.rotate(angle*Math.PI/180);g.drawImage(bitmap,-w/2,-h/2,w,h);return c}
async function recognize(file,signal){const bitmap=await raceAbort(createImageBitmap(file),signal);let best=null;try{const w=await worker(signal);await raceAbort(w.setParameters({tessedit_pageseg_mode:'3'}),signal);for(const angle of [0,90,270,180]){if(signal.aborted)throw cancelled();if($('#angleStatus'))$('#angleStatus').textContent=angle?'正在检查照片方向（'+angle+'°）…':'正在识别并搜索全部年份…';const c=canvasFor(bitmap,angle),{data}=await raceAbort(w.recognize(c,{},{text:true,blocks:true}),signal),raw=[];for(const b of data.blocks||[])for(const p of b.paragraphs||[])for(const l of p.lines||[])for(const word of l.words||[])if(word.confidence>=20&&word.text.trim())raw.push({text:word.text,x:word.bbox.x0/c.width*100,y:word.bbox.y0/c.height*100,w:(word.bbox.x1-word.bbox.x0)/c.width*100,h:(word.bbox.y1-word.bbox.y0)/c.height*100});const ranked=ExamMatch.rank(raw.map(w=>w.text).join(' '),U.index),decision=ExamMatch.decide(ranked);const merit=(ranked[0]?.score||0)*Math.min(1,(ranked[0]?.phrases||0)/20);if(!best||merit>best.merit){const turn=ExamMatch.orientation(raw,c.width,c.height),upright=turn?canvasFor(bitmap,(angle+turn)%360):c;best={raw:ExamMatch.rotateBoxes(raw,turn),ranked,decision,angle:(angle+turn)%360,merit,blob:await new Promise(resolve=>upright.toBlob(resolve,'image/jpeg',.86))}}if(decision.accepted)break}return best}finally{bitmap.close()}}
function renderQueue(){if(!$('#queueList'))return;$('#queueList').innerHTML=U.queue.map(x=>'<div class="queue-item"><span>'+esc(x.name)+'</span><small>'+esc(x.status)+'</small></div>').join('')}
async function importPhotos(files){if(U.busy){toast('正在处理照片，可先取消当前识别');return}if(!U.index){toast('资料库尚未准备好，请稍候');return}files=[...files];if(!files.length)return;if(files.length>10){toast('一次最多处理 10 张照片');return}const good=[],errors=[];for(const file of files){if(!/^image\/(jpeg|png|webp|bmp)$/.test(file.type)&&! /\.(jpg|jpeg|png|webp)$/i.test(file.name)){errors.push(file.name+'：格式不支持');continue}if(file.size>20*1024*1024){errors.push(file.name+'：超过 20 MB');continue}good.push(file)}if(!good.length){dialog('照片未导入','<div class="error-box">'+errors.map(esc).join('<br>')+'</div>');return}U.busy=true;U.abort=new AbortController();const signal=U.abort.signal;U.queue=good.map(f=>({name:f.name,status:'等待识别',result:null}));dialog('自动识别作答照片','<p class="busy-note">首次需要加载识别组件。每张照片会按内容搜索资料库，并尝试校正方向。</p><div id="queueList"></div><div class="progress-track"><i id="progressBar" style="width:0%"></i></div><p id="ocrStatus" role="status">准备中…</p><p id="angleStatus" class="muted"></p><button id="cancelOCR">取消剩余识别</button>'+(errors.length?'<div class="error-box">'+errors.map(esc).join('<br>')+'</div>':''));$('#cancelOCR').onclick=cancelOCR;renderQueue();for(let i=0;i<good.length;i++){if(signal.aborted)break;const row=U.queue[i];row.status='识别中';renderQueue();try{const r=await recognize(good[i],signal);if(signal.aborted)throw cancelled();if(!r?.blob)throw Error('图片处理失败，请重试');row.result=r;if(r.decision.accepted){row.photo=await storePhoto(good[i].name,r,r.ranked[0].page);row.status='已对应 '+r.ranked[0].page.year+' · 第 '+r.ranked[0].page.page+' 页'}else row.status=r.decision.reason}catch(e){row.status=e.name==='AbortError'?'已取消':e.message||'识别失败'}renderQueue();if($('#progressBar'))$('#progressBar').style.width=((i+1)/good.length*100)+'%'}U.busy=false;U.abort=null;for(const r of U.queue)if(r.status==='等待识别')r.status='已取消';if(!signal.aborted)showImportResults();else toast('识别已取消，已完成的照片保留在“我的照片”')}
function cancelOCR(){U.abort?.abort();if(U.worker){U.worker.terminate();U.worker=null}if($('#dialog').open)$('#dialog').close()}
async function storePhoto(name,r,page){const id=crypto.randomUUID(),record={id,name,pageId:page.id,year:page.year,page:page.page,section:page.section,createdAt:new Date().toISOString(),questionNumber:ExamMatch.questionFromPhoto(r.raw,page),blob:r.blob,words:ExamMatch.align(r.raw,page.words),angle:r.angle};let saved=true;try{await dbAction('readwrite',s=>s.put(record))}catch{saved=false;toast('照片暂时可用，但此浏览器未能保存图片，刷新后需重新导入')}const url=URL.createObjectURL(r.blob);U.urls.push(url);return {...record,url,saved}}
function showImportResults(){dialog('识别结果','<p class="muted">已匹配的照片可以直接复盘；未确定的照片请检查候选。相似度只用于排序，不代表准确率。</p><div id="resultList">'+U.queue.map((r,i)=>'<div class="queue-item"><div><strong>'+esc(r.name)+'</strong><br><small>'+esc(r.status)+'</small></div>'+(r.photo?'<button data-open-result="'+i+'" class="primary">打开解析</button>':r.result?'<button data-review-result="'+i+'">核对候选</button>':'')+'</div>').join('')+'</div>');document.querySelectorAll('[data-open-result]').forEach(b=>b.onclick=()=>{const r=U.queue[Number(b.dataset.openResult)];$('#dialog').close();openPage(U.pages.find(p=>p.id===r.photo.pageId),r.photo,'照片已自动对应')});document.querySelectorAll('[data-review-result]').forEach(b=>b.onclick=()=>showCandidates(Number(b.dataset.reviewResult)))}
function showCandidates(i){const row=U.queue[i],r=row.result,url=URL.createObjectURL(r.blob);U.urls.push(url);dialog('核对照片对应的真题','<img class="photo-preview" src="'+url+'" alt="待核对的作答照片"><div class="error-box">'+esc(r.decision.reason)+'。只拍选项、指令或内容太少时，请补拍完整题干。</div><div class="candidates">'+r.ranked.map((x,j)=>'<button class="candidate" data-candidate="'+j+'"><div><strong>'+x.page.year+' 英语二 · '+esc(x.page.section)+'</strong><p>第 '+x.page.page+' 页 · '+esc(x.page.text.replace(/\s+/g,' ').slice(0,80))+'…</p></div><small>选择这页</small></button>').join('')+'</div><p class="muted">都不对应：请重新拍摄，或补充未收录的真题资料。不要选择不相符的年份。</p><button id="resultsBack">返回结果</button>');$('#resultsBack').onclick=showImportResults;document.querySelectorAll('[data-candidate]').forEach(b=>b.onclick=async()=>{b.disabled=true;const page=r.ranked[Number(b.dataset.candidate)].page;row.photo=await storePhoto(row.name,r,page);row.status='人工确认 '+page.year+' 第 '+page.page+' 页';$('#dialog').close();openPage(page,row.photo,'照片经你核对对应')})}
async function showHistory(){try{const rows=(await dbAction('readonly',s=>s.getAll())).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));dialog('我的作答照片',rows.length?'<div class="history-list">'+rows.map((r,i)=>{const url=URL.createObjectURL(r.blob);U.urls.push(url);r.url=url;return '<div class="history-card"><img src="'+url+'" alt="'+r.year+' 年作答照片"><strong>'+r.year+' · '+esc(r.section)+' · 第 '+r.page+' 页</strong><small>'+esc(r.name)+'</small><button data-history="'+i+'">继续复盘</button><button data-delete-photo="'+i+'">删除</button></div>'}).join('')+'</div>':'<div class="empty">还没有保存的照片。上传一张，开始复盘。</div>');document.querySelectorAll('[data-history]').forEach(b=>b.onclick=()=>{const r=rows[Number(b.dataset.history)];$('#dialog').close();openPage(U.pages.find(p=>p.id===r.pageId),r,'已保存的作答照片')});document.querySelectorAll('[data-delete-photo]').forEach(b=>b.onclick=async()=>{const r=rows[Number(b.dataset.deletePhoto)];await dbAction('readwrite',s=>s.delete(r.id));showHistory();toast('照片已删除，作答笔记仍保留')})}catch(e){dialog('我的作答照片','<div class="error-box">'+esc(e.message||'无法读取已保存照片')+'</div>')}}
function download(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function showRecords(){const entries=Object.entries(U.records).sort((a,b)=>a[0].localeCompare(b[0]));dialog('学习记录','<div class="action-row"><button id="exportRecords" class="primary">导出记录</button><button id="importRecords">恢复备份</button></div><input id="recordFile" type="file" accept=".json,application/json" hidden><div id="restorePreview" role="status"></div><p class="muted">共 '+entries.length+' 题。备份包含原始作答和笔记，不包含照片。2010 精读版的记录仍在原页面独立保存。</p>'+entries.map(([key,r])=>'<div class="record-row"><strong>'+key.split('-')[0]+' 年 · 第 '+key.split('-')[1]+' 题 · 作答 '+esc(r.answer||'未记录')+'</strong><p>'+esc(r.note||'暂无笔记')+'</p></div>').join(''));$('#exportRecords').onclick=()=>download({schema:1,records:U.records},'英语二-通用版学习记录.json');$('#importRecords').onclick=()=>$('#recordFile').click();$('#recordFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5e6)throw Error('文件过大');const records=validateRecords(JSON.parse(await file.text()));$('#restorePreview').innerHTML='<div class="error-box">已校验 '+Object.keys(records).length+' 题。恢复将替换当前记录，并先下载当前记录作为备份。<button id="applyRestore">备份当前记录并恢复</button></div>';$('#applyRestore').onclick=()=>{try{download({schema:1,records:U.records},'英语二-恢复前备份.json');localStorage.setItem(RECORD_KEY,JSON.stringify({schema:1,records}));U.records=records;showRecords();if(U.page)renderQuestions();toast('记录已恢复')}catch{toast('无法保存恢复记录')}}}catch(e){$('#restorePreview').textContent='无法恢复：'+e.message}}}
document.addEventListener('click',e=>{const b=e.target.closest('button,rect');if(!b)return;if(b.dataset.year)openPage(U.pages.find(p=>p.year===Number(b.dataset.year)&&p.page===3));if(b.dataset.view){U.view=b.dataset.view;renderSource()}if(b.dataset.mode){U.mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('active',x.dataset.mode===U.mode));if(U.lookup)lookup(U.lookup.text,U.lookup.index)}if(b.dataset.panel){if(b.dataset.panel==='explanation')showExplanation();else{setPanel('lookup');if(U.lookup)lookup(U.lookup.text,U.lookup.index);else{$('#detailContent').innerHTML='<div class="empty">点击原题或照片中的单词查词；切换“句子”查看整句所在的原书译文与讲解。</div>'}}}if(b.dataset.question){U.question=Number(b.dataset.question);renderQuestions();showExplanation()}if(b.dataset.answer)setAnswer(b.dataset.answer);if(b.dataset.wordIndex!==undefined){const i=Number(b.dataset.wordIndex);lookup(U.page.words[i].text,i)}if(b.dataset.hit!==undefined){const i=Number(b.dataset.hit),w=U.view==='photo'?U.photo.words[i]:U.page.words[i];lookup(w.text,U.view==='photo'?w.index:i)}});
$('#sourceContent').addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)&&e.target.dataset.hit!==undefined){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}});
for(const id of ['pickPhotos','addPhotos'])$('#'+id).onclick=()=>$('#photoInput').click();$('#cameraButton').onclick=()=>$('#cameraInput').click();for(const id of ['photoInput','cameraInput'])$('#'+id).onchange=e=>{importPhotos(e.target.files);e.target.value=''};
$('#dropZone').ondragover=e=>{e.preventDefault();$('#dropZone').classList.add('drag')};$('#dropZone').ondragleave=()=>$('#dropZone').classList.remove('drag');$('#dropZone').ondrop=e=>{e.preventDefault();$('#dropZone').classList.remove('drag');importPhotos(e.dataTransfer.files)};
$('#pageSelect').onchange=e=>openPage(U.pages.find(p=>p.id===e.target.value));$('#backHome').onclick=()=>{U.loadToken++;$('#workbench').hidden=true;$('#home').hidden=false};$('#historyButton').onclick=showHistory;$('#recordsButton').onclick=showRecords;$('#closeDialog').onclick=()=>{if(U.busy)cancelOCR();else $('#dialog').close()};$('#dialog').addEventListener('cancel',()=>{if(U.busy)cancelOCR()});
$('#zoomOut').onclick=()=>{U.zoom=Math.max(1,U.zoom-.2);renderSource()};$('#zoomIn').onclick=()=>{U.zoom=Math.min(2.6,U.zoom+.2);renderSource()};
window.addEventListener('beforeunload',e=>{if(U.busy){e.preventDefault();e.returnValue=''}});
async function init(){try{try{const raw=localStorage.getItem(RECORD_KEY);if(raw)U.records=validateRecords(JSON.parse(raw))}catch{U.storageDamaged=true;toast('本地记录无法读取，原存储未删除，请用备份恢复')}U.catalog=await json('library/catalog.json');U.pages=(await Promise.all(U.catalog.years.map(y=>json(y.exam)))).flat();U.index=ExamMatch.build(U.pages);$('#librarySummary').textContent=U.catalog.years.length+' 套真题 · '+U.pages.length+' 页 · 13 套解析';$('#yearGrid').innerHTML=U.catalog.years.map(y=>'<button class="year-card '+(!y.reference?'missing':'')+'" data-year="'+y.year+'"><strong>'+y.year+'</strong><small>'+(y.reference?'原题 + 原书解析':'原题 · 解析待补')+'</small></button>').join('');U.dictionary=await json('library/dictionary.json')}catch(e){$('#yearGrid').innerHTML='<div class="load-error">'+esc(e.message)+'<button id="reloadLibrary">重新加载</button></div>';$('#reloadLibrary').onclick=init}}
init();
